package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import com.creatorhub.model.Application; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; @WebServlet("/apply") public class ApplyServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("studentId")==null){s.sendRedirect(r.getContextPath()+"/?error=Login+to+apply");return;}try{Application a=new Application();a.setCollabId(Integer.parseInt(r.getParameter("collabId")));a.setApplicantId((Integer)h.getAttribute("studentId"));a.setPitchText(r.getParameter("pitchText"));boolean ok=new CreatorDAO().apply(a);s.sendRedirect(r.getContextPath()+"/discover?message="+(ok?"Application+submitted":"Already+applied"));}catch(Exception e){s.sendRedirect(r.getContextPath()+"/discover?error=Application+failed");}}}
